import React, { useState } from 'react';
import { Calendar, Clock, History, ChevronLeft, ChevronRight, ListFilter } from 'lucide-react';

const CollectionScheduleTab = () => {
  const [viewMode, setViewMode] = useState('CURRENT'); // 'CURRENT' or 'HISTORY'
  const [historyFilter, setHistoryFilter] = useState('WEEK'); // 'WEEK' or 'MONTH'

  const currentSchedule = [
    { id: 'SCH-01', route: 'R-NORTH-01', driver: 'Arjun V.', time: '06:00 AM', status: 'IN_PROGRESS' },
    { id: 'SCH-02', route: 'R-CENTRAL-04', driver: 'Sarah K.', time: '08:30 AM', status: 'PENDING' },
    { id: 'SCH-03', route: 'R-IND-09', driver: 'Mike T.', time: '10:00 AM', status: 'PENDING' },
  ];

  const historyData = [
    { id: 'H-992', date: '2026-03-18', route: 'R-NORTH-01', totalBins: 45, efficiency: '98%', status: 'COMPLETED' },
    { id: 'H-991', date: '2026-03-17', route: 'R-WEST-02', totalBins: 32, efficiency: '92%', status: 'COMPLETED' },
    { id: 'H-990', date: '2026-03-16', route: 'R-SOUTH-08', totalBins: 50, efficiency: '85%', status: 'COMPLETED' },
  ];

  return (
    <div className="w-full animate-slot flex flex-col gap-6">

      {/* HEADER & TOGGLE CONTROL */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[30px] p-6 shadow-[8px_8px_0_0_#47510B]">
        <div className="flex items-center gap-4">
          <div className="bg-[#AB1717] p-3 rounded-2xl border-4 border-[#47510B]">
            <Calendar size={24} className="text-[#FDFAD8]" />
          </div>
          <div>
            <h2 className="text-2xl font-[1000] italic text-[#47510B] uppercase leading-none tracking-tighter">03_COLLECTION_LOGS</h2>
            <p className="text-[10px] font-black text-[#AB1717] uppercase tracking-widest mt-1">Sync_Status: Real_Time</p>
          </div>
        </div>

        {/* MODE SWITCHER */}
        <div className="flex bg-[#47510B] p-1 rounded-xl border-2 border-[#47510B]">
          <button 
            onClick={() => setViewMode('CURRENT')}
            className={`px-6 py-2 rounded-lg font-black text-[10px] uppercase transition-all ${viewMode === 'CURRENT' ? 'bg-[#CAD23C] text-[#47510B]' : 'text-[#FDFAD8] hover:bg-[#FDFAD8]/10'}`}
          >
            Live_Schedule
          </button>
          <button 
            onClick={() => setViewMode('HISTORY')}
            className={`px-6 py-2 rounded-lg font-black text-[10px] uppercase transition-all ${viewMode === 'HISTORY' ? 'bg-[#CAD23C] text-[#47510B]' : 'text-[#FDFAD8] hover:bg-[#FDFAD8]/10'}`}
          >
            History_Archive
          </button>
        </div>
      </div>

      {/* VIEW 1: LIVE SCHEDULE */}
      {viewMode === 'CURRENT' ? (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {currentSchedule.map((item) => (
            <div key={item.id} className="bg-white border-[5px] border-[#47510B] rounded-[25px] p-5 shadow-[6px_6px_0_0_#CAD23C] relative overflow-hidden">
               <div className="flex justify-between items-start mb-4">
                  <div className="bg-[#47510B] text-[#FDFAD8] text-[8px] font-black px-2 py-1 rounded italic">{item.id}</div>
                  <div className={`text-[8px] font-black uppercase ${item.status === 'IN_PROGRESS' ? 'text-[#AB1717] animate-pulse' : 'text-[#47510B]'}`}>
                    ● {item.status.replace('_', ' ')}
                  </div>
               </div>
               <h4 className="text-lg font-black text-[#47510B] uppercase italic mb-1">{item.route}</h4>
               <p className="text-[10px] font-bold text-[#47510B]/60 mb-4 flex items-center gap-1 uppercase tracking-tighter">
                  <Clock size={12} /> Start_Time: {item.time}
               </p>
               <div className="bg-[#FDFAD8] border-2 border-[#47510B] p-3 rounded-xl flex items-center justify-between">
                  <span className="text-[10px] font-black text-[#47510B]">DRIVER:</span>
                  <span className="text-[10px] font-black text-[#AB1717] uppercase italic">{item.driver}</span>
               </div>
            </div>
          ))}
        </div>
      ) : (
        /* VIEW 2: HISTORY LOGS */
        <div className="flex flex-col gap-4 animate-slot">
          {/* HISTORY FILTERS */}
          <div className="flex gap-2 mb-2">
            <button 
              onClick={() => setHistoryFilter('WEEK')}
              className={`px-4 py-1 rounded-full border-2 border-[#47510B] text-[9px] font-black uppercase ${historyFilter === 'WEEK' ? 'bg-[#47510B] text-[#CAD23C]' : 'bg-white text-[#47510B]'}`}
            >
              Past_7_Days
            </button>
            <button 
              onClick={() => setHistoryFilter('MONTH')}
              className={`px-4 py-1 rounded-full border-2 border-[#47510B] text-[9px] font-black uppercase ${historyFilter === 'MONTH' ? 'bg-[#47510B] text-[#CAD23C]' : 'bg-white text-[#47510B]'}`}
            >
              Monthly_Report
            </button>
          </div>

          <div className="bg-white border-[6px] border-[#47510B] rounded-[35px] overflow-hidden shadow-2xl">
            <table className="w-full text-left">
              <thead className="bg-[#47510B] text-[#FDFAD8] text-[9px] font-black uppercase italic tracking-widest">
                <tr>
                  <th className="p-5 border-r border-[#FDFAD8]/10 text-center">Date</th>
                  <th className="p-5 border-r border-[#FDFAD8]/10">Route_Code</th>
                  <th className="p-5 border-r border-[#FDFAD8]/10 text-center">Bins_Cleared</th>
                  <th className="p-5 text-center">Efficiency</th>
                </tr>
              </thead>
              <tbody className="text-[#47510B] font-bold text-sm italic">
                {historyData.map((log) => (
                  <tr key={log.id} className="border-b-2 border-[#47510B]/5 hover:bg-[#CAD23C]/20 transition-colors">
                    <td className="p-5 border-r border-[#47510B]/5 text-center font-mono">{log.date}</td>
                    <td className="p-5 border-r border-[#47510B]/5 uppercase">{log.route}</td>
                    <td className="p-5 border-r border-[#47510B]/5 text-center font-black">{log.totalBins}</td>
                    <td className="p-5 text-center">
                      <span className="bg-[#47510B] text-[#CAD23C] px-3 py-1 rounded-md text-[10px]">{log.efficiency}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default CollectionScheduleTab;
